import { Component, OnInit } from '@angular/core';

interface MathQuestion {
  num1: number;
  num2: number;
  operation: '+' | '-';
  correctAnswer: number;
  options: number[];
  visualIcon: string;
}

@Component({
  selector: 'app-math-practice',
  templateUrl: './math-practice.component.html',
  styleUrls: ['./math-practice.component.scss']
})
export class MathPracticeComponent implements OnInit {

  // حالت‌های تمرین
  mode: 'addition' | 'subtraction' | 'mixed' = 'addition';
  maxRange: 10 | 20 = 10;

  // وضعیت بازی
  currentQuestion: MathQuestion;
  score = 0;
  streak = 0;
  totalAnswered = 0;
  answered = false;
  selectedAnswer: number | null = null;
  isCorrect = false;

  // لیست آیکون‌های کودکانه برای تجسم عینی دست‌ورزی
  icons = ['🍎', '⭐️', '🚗', '🐱', '✏️', '🎈', '🌸', '🍭'];

  // محور اعداد تعاملی
  numberLineMax = 10;
  numberLineArray: number[] = [];

  ngOnInit(): void {
    this.updateNumberLine();
    this.generateNewQuestion();
  }

  setMode(newMode: 'addition' | 'subtraction' | 'mixed'): void {
    this.mode = newMode;
    this.generateNewQuestion();
  }

  setRange(range: 10 | 20): void {
    this.maxRange = range;
    this.numberLineMax = range;
    this.updateNumberLine();
    this.generateNewQuestion();
  }

  updateNumberLine(): void {
    this.numberLineArray = Array.from({ length: this.numberLineMax + 1 }, (_, i) => i);
  }

  generateNewQuestion(): void {
    this.answered = false;
    this.selectedAnswer = null;

    let op: '+' | '-' = '+';
    if (this.mode === 'addition') {
      op = '+';
    } else if (this.mode === 'subtraction') {
      op = '-';
    } else {
      op = Math.random() > 0.5 ? '+' : '-';
    }

    let n1 = 0;
    let n2 = 0;
    let ans = 0;

    if (op === '+') {
      n1 = Math.floor(Math.random() * (this.maxRange - 1)) + 1;
      n2 = Math.floor(Math.random() * (this.maxRange - n1 + 1));
      ans = n1 + n2;
    } else {
      n1 = Math.floor(Math.random() * this.maxRange) + 1;
      n2 = Math.floor(Math.random() * (n1 + 1));
      ans = n1 - n2;
    }

    // گزینه‌های پاسخ ۴ تایی
    const optionsSet = new Set<number>();
    optionsSet.add(ans);
    while (optionsSet.size < 4) {
      const delta = (Math.random() > 0.5 ? 1 : -1) * (Math.floor(Math.random() * 3) + 1);
      const fake = Math.max(0, Math.min(this.maxRange, ans + delta));
      optionsSet.add(fake);
    }

    const options = Array.from(optionsSet).sort(() => 0.5 - Math.random());
    const visualIcon = this.icons[Math.floor(Math.random() * this.icons.length)];

    this.currentQuestion = {
      num1: n1,
      num2: n2,
      operation: op,
      correctAnswer: ans,
      options,
      visualIcon
    };
  }

  submitAnswer(choice: number): void {
    if (this.answered) { return; }
    this.selectedAnswer = choice;
    this.answered = true;
    this.totalAnswered++;

    if (choice === this.currentQuestion.correctAnswer) {
      this.isCorrect = true;
      this.score += 10;
      this.streak++;
    } else {
      this.isCorrect = false;
      this.streak = 0;
    }
  }

  getVisualArray(count: number): number[] {
    return Array.from({ length: Math.max(0, count) }, (_, i) => i);
  }
}
